<?php
namespace Tests\Feature;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Cache;use Tests\TestCase;
class SecurityHealthTest extends TestCase {use RefreshDatabase;public function test_security_headers_are_present():void{$this->get('/')->assertOk()->assertHeader('X-Content-Type-Options','nosniff')->assertHeader('X-Frame-Options','SAMEORIGIN')->assertHeader('Referrer-Policy','strict-origin-when-cross-origin');}public function test_health_check_has_no_configuration_secrets():void{Cache::put('queue.heartbeat',now(),60);$response=$this->getJson('/health')->assertOk()->assertJsonPath('status','ok');$body=$response->getContent();$this->assertStringNotContainsString((string)config('app.key'),$body);$this->assertArrayHasKey('database',$response->json('checks'));}}
